#!/usr/bin/env python3
"""Render the reviewable coverage matrix from the executable manifest."""

import argparse
from collections import Counter
import json
import os
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]


def render(manifest):
    counts = Counter(case["kind"] for case in manifest["cases"])
    lines = [
        "# The 100-case coverage matrix",
        "",
        "Generated by `python3 scripts/coverage.py` from `tests/cases.json`.",
        "Each row is one distinct entry point and behavioral or rejection contract.",
        "Sample inputs inside a row are assertions, not additional counted cases.",
        "",
        f'**{counts["run"]} runtime programs + {counts["proof"]} proof projects + {counts["reject"]} expected rejections = {sum(counts.values())} cases.**',
        "",
        "The count includes the original seven programs (r01–r03, r21, r41–r43),",
        "the original counter proof (p01), and original nine rejection cases (n01–n09).",
        "Thus 83 cases are new. Support modules, 15 fixed-law mutations, two additional proof-guard checks, harness",
        "unit tests and fresh-agent tasks are not counted toward 100.",
        "",
        "No verified BendHub package cases are included. The [package access record](validation/2026-10-24-bendhub.md)",
        "documents why the requested registry-backed extension remains blocked; source-backed guidance is available",
        "in the [package reference](skills/bend-best-practices/references/packages.md).",
        "",
        "Runtime outputs are exact assertions established from the stated oracle.",
        "Proof projects require both ordinary checker and no-main proof-gate acceptance;",
        "their 19 law declarations are SHA256-pinned. Every proof project also has a",
        "[targeted mutation](tests/findings/proof-mutations.md) with unchanged LAWS;",
        "13 mutated implementations must still pass standalone checking, while their proofs fail.",
        "The other two mutations reject an incorrect proof/witness. Rejections require exit 1, the Bend failure",
        "verdict, and a case-specific diagnostic. None establishes BendTT, native/GPU",
        "execution, parallel scheduling, performance, or broad agent effectiveness.",
        "",
        "| ID | Category | Contract and independent oracle | Source |",
        "|---|---|---|---|",
    ]
    for case in manifest["cases"]:
        purpose = case["purpose"].replace("|", "\\|").replace("\n", " ")
        oracle = case["oracle"].replace("|", "\\|").replace("\n", " ")
        lines.append(f'| {case["id"]} ({case["kind"]}) | {case["category"]} | **{purpose}** {oracle} | [source]({case["file"]}) |')
    lines.extend(["", "See [VALIDATION.md](VALIDATION.md) for actual runs, failures found, fixes and limits.", ""])
    return "\n".join(lines)


def example_index(manifest):
    directory = ROOT / 'skills/bend-best-practices/references'
    link = lambda name: os.path.relpath(ROOT / name, directory)
    lines = ['# Example index', '',
             'Bend **2.0.39**, pinned in [sources](sources.md). Generated from the repository',
             'manifest by `scripts/coverage.py`; this index and all linked examples travel',
             'with the standalone skill. The repository adds 25 rejection fixtures, fixed-law',
             'mutations and a repeatable runner. See its `VALIDATION.md` for dated evidence.', '',
             'These examples use Base and local modules. [BendHub guidance](packages.md)',
             'is source-backed documentation; real-package examples remain blocked by registry access.', '',
             '## Law and proof projects', '',
             'Read the law before the implementation or proof. These 15 projects contain 19',
             'law declarations, accepted by the ordinary checker. Each has a targeted',
             'mutation checked by the repository runner. **BendTT kernel verification has',
             'not run successfully.** The claims establish the named invariants only;',
             'see [proof scope](proofs.md#use-laws-to-drive-the-implementation).', '',
             '| ID | Invariant / obligation | Specification | Proof |',
             '|---|---|---|---|']
    for c in manifest['cases']:
        if c['kind'] == 'proof':
            lines.append(f'| {c["id"]} | {c["purpose"]} | [LAWS]({link(c["law_file"])}) | [PROOF]({link(c["file"])}) |')
    lines += ['', '## Runtime programs', '',
              'All 60 programs require checker acceptance, JS emission and exact Node output.',
              '53 also assert normalization output. Five IO programs and two F32 programs',
              'use compiled execution for concrete results. These sample assertions do not',
              'prove universal correctness, native/GPU execution or performance.', '',
              '| ID | Program / purpose | Exact stdout (line breaks shown as `\\n`) |',
              '|---|---|---|']
    for c in manifest['cases']:
        if c['kind'] == 'run':
            out = c['stdout'].replace('\n', '\\n').replace('|', '&#124;')
            lines.append(f'| {c["id"]} | [{Path(c["file"]).stem}]({link(c["file"])}) — {c["purpose"]} | `{out}` |')
    return '\n'.join(lines) + '\n'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if the checked-in matrix is stale")
    args = parser.parse_args()
    manifest = json.loads((ROOT / 'tests/cases.json').read_text())
    outputs = {ROOT / 'COVERAGE.md': render(manifest),
               ROOT / 'skills/bend-best-practices/references/examples.md': example_index(manifest)}
    for output, expected in outputs.items():
        if args.check:
            if not output.exists() or output.read_text() != expected:
                print(f'{output.name} is stale; run python3 scripts/coverage.py', file=sys.stderr)
                return 1
        else:
            output.write_text(expected)
    if args.check:
        print('PASS coverage matrix and standalone example index match manifest')
    return 0


if __name__ == "__main__":
    sys.exit(main())
